	one := big.NewInt(1)

	// Generate a random number less than N
	limit := new(big.Int).Sub(N, one)
	n.Rand(r, limit)
	n.Add(n, one) // Ensure it's between 1 and N-1

	n.SetBit(n, 0, 1) // Make it odd

	return n, nil
