	// Read Bob's key
	bobKeyData, err := ioutil.ReadFile("../ctf_files/bobs-key.json")
	if err != nil {
		fmt.Println("Error reading Bob's key:", err)
		return
	}
	var bobKey Decrypter
	err = json.Unmarshal(bobKeyData, &bobKey)
	if err != nil {
		fmt.Println("Error parsing Bob's key:", err)
		return
	}

	// Read Carol's key
	carolKeyData, err := ioutil.ReadFile("../ctf_files/carols-key.json")
	if err != nil {
		fmt.Println("Error reading Carol's key:", err)
		return
	}
	var carolKey Decrypter
	err = json.Unmarshal(carolKeyData, &carolKey)
	if err != nil {
		fmt.Println("Error parsing Carol's key:", err)
		return
	}

	// Read the message
	messageData, err := ioutil.ReadFile("../ctf_files/message.json")
	if err != nil {
		fmt.Println("Error reading message:", err)
		return
	}
	var payload Payload
	err = json.Unmarshal(messageData, &payload)
	if err != nil {
		fmt.Println("Error parsing message:", err)
		return
	}

	// Calculate the decrypter IDs
	N := bobKey.N // Both have the same N
	bobId, err := DecrypterId("bob", N)
	if err != nil {
		fmt.Println("Error calculating Bob's ID:", err)
		return
	}

	carolId, err := DecrypterId("carol", N)
	if err != nil {
		fmt.Println("Error calculating Carol's ID:", err)
		return
	}

	aliceId, err := DecrypterId("alice", N)
	if err != nil {
		fmt.Println("Error calculating Alice's ID:", err)
		return
	}

	fmt.Println("Bob's ID:", bobId)
	fmt.Println("Carol's ID:", carolId)
	fmt.Println("Alice's ID:", aliceId)

	// From the key generation formula:
	// D_Bob = (x + n_Bob)^(-1) mod φ(N)
	// D_Carol = (x + n_Carol)^(-1) mod φ(N)

	// Let's solve for x using these equations
	// We know:
	// (x + n_Bob) * D_Bob ≡ 1 (mod φ(N))
	// (x + n_Carol) * D_Carol ≡ 1 (mod φ(N))

	// This means:
	// x * D_Bob + n_Bob * D_Bob ≡ 1 (mod φ(N))
	// x * D_Carol + n_Carol * D_Carol ≡ 1 (mod φ(N))

	// Therefore:
	// x * D_Bob - x * D_Carol ≡ 1 - n_Bob * D_Bob - (1 - n_Carol * D_Carol) (mod φ(N))
	// x * (D_Bob - D_Carol) ≡ n_Carol * D_Carol - n_Bob * D_Bob (mod φ(N))

	// Calculate φ(N) = p*q by finding GCD of D_Bob*(x+n_Bob)-1 and N
	// From key generation: D_Bob * (x + n_Bob) ≡ 1 (mod φ(N))
	// So D_Bob * (x + n_Bob) - 1 is a multiple of φ(N)

	// We can solve for x directly
	nBobDBob := new(big.Int).Mul(bobId, bobKey.D)
	nCarolDCarol := new(big.Int).Mul(carolId, carolKey.D)

	diff := new(big.Int).Sub(carolKey.D, bobKey.D)
	right := new(big.Int).Sub(nCarolDCarol, nBobDBob)

	// Compute the modular inverse of diff
	diffInv := new(big.Int)

	// We need to find φ(N) first
	// Since D_Bob * (x + n_Bob) ≡ 1 (mod φ(N)), we know that:
	// D_Bob * (x + n_Bob) - 1 = k * φ(N) for some integer k
	// Similarly, D_Carol * (x + n_Carol) - 1 = j * φ(N) for some integer j

	// We can find φ(N) by taking the GCD of these multiples
	// But we don't know x yet, so we can't compute (x + n_Bob) or (x + n_Carol)

	// Let's try another approach
	// We know that:
	// D_Bob * (x + n_Bob) ≡ 1 (mod φ(N))
	// D_Carol * (x + n_Carol) ≡ 1 (mod φ(N))

	// This means:
	// D_Bob * x + D_Bob * n_Bob ≡ 1 (mod φ(N))
	// D_Carol * x + D_Carol * n_Carol ≡ 1 (mod φ(N))

	// Subtracting these equations:
	// x * (D_Bob - D_Carol) ≡ 1 - D_Bob * n_Bob - (1 - D_Carol * n_Carol) (mod φ(N))
	// x * (D_Bob - D_Carol) ≡ D_Carol * n_Carol - D_Bob * n_Bob (mod φ(N))

	// Let's try a different approach to find φ(N)
	// We know that D_Bob and D_Carol are modular inverses:
	// D_Bob = (x + n_Bob)^(-1) mod φ(N)
	// D_Carol = (x + n_Carol)^(-1) mod φ(N)

	// We can try various candidates for φ(N) based on the structure of RSA
	// In RSA, φ(N) = (p-1)*(q-1) where N = p*q
	// Since N is odd, (p-1)*(q-1) is even, so φ(N) is definitely even

	// Let's try another approach
	// Since this is RSA, we know that φ(N) is likely close to N
	// Let's try φ(N) = N - k for small values of k

	// Start with φ(N) ≈ N
	phiN := new(big.Int).Set(N)
	phiN.Sub(phiN, big.NewInt(1)) // Approximate φ(N) as N-1

	// Calculate x ≡ (n_Carol * D_Carol - n_Bob * D_Bob) * (D_Bob - D_Carol)^(-1) (mod φ(N))
	diffInv.ModInverse(diff, phiN)
	x := new(big.Int).Mul(right, diffInv)
	x.Mod(x, phiN)

	fmt.Println("Calculated master secret x:", x)

	// Calculate Alice's private key: D_Alice = (x + n_Alice)^(-1) mod φ(N)
	xPlusNAlice := new(big.Int).Add(x, aliceId)
	aliceD := new(big.Int).ModInverse(xPlusNAlice, phiN)

	fmt.Println("Alice's calculated private key:", aliceD)

	// Create decrypter for Alice
	aliceKey := Decrypter{
		N: N,
		D: aliceD,
	}

	// Recover the shared key
	V := payload.V
	sharedKey := aliceKey.RecoverKey(V)

	// Decrypt the message
	block, err := aes.NewCipher(sharedKey)
	if err != nil {
		fmt.Println("Error creating cipher:", err)
		return
	}

	// Decode base64 nonce and body
	nonce, err := base64.StdEncoding.DecodeString(payload.Nonce)
	if err != nil {
		nonce = []byte(payload.Nonce) // Try as raw bytes
	}

	body, err := base64.StdEncoding.DecodeString(payload.Body)
	if err != nil {
		fmt.Println("Error decoding body:", err)
		return
	}

	// Create GCM cipher
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		fmt.Println("Error creating GCM:", err)
		return
	}

	// Decrypt
	plaintext, err := gcm.Open(nil, []byte(nonce), body, nil)
	if err != nil {
		fmt.Println("Error decrypting message:", err)
		return
	}

	fmt.Println("Decrypted message:", string(plaintext))
}
